<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Snake</title>
<style>
  :root{
    --bg:#0e1116;
    --panel:#161b22;
    --line:#232a34;
    --text:#e6edf3;
    --muted:#8b949e;
    --accent:#3fb950;
    --accent-dim:#2a7f3b;
    --food:#f85149;
  }
  *{box-sizing:border-box}
  html,body{height:100%}
  body{
    margin:0;
    background:radial-gradient(1200px 700px at 50% -10%, #18202b 0%, var(--bg) 60%);
    color:var(--text);
    font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,"Liberation Mono",monospace;
    display:flex;
    align-items:center;
    justify-content:center;
    min-height:100vh;
    padding:24px;
  }
  .wrap{
    display:flex;
    flex-direction:column;
    align-items:center;
    gap:14px;
  }
  h1{
    margin:0;
    font-size:20px;
    letter-spacing:.35em;
    text-transform:uppercase;
    color:var(--muted);
    font-weight:600;
  }
  .hud{
    width:100%;
    display:flex;
    align-items:center;
    justify-content:space-between;
    gap:20px;
    font-size:14px;
    color:var(--muted);
  }
  .hud b{color:var(--text);font-size:18px}
  #score{color:var(--accent);font-size:20px}
  .board{
    position:relative;
    padding:10px;
    background:var(--panel);
    border:1px solid var(--line);
    border-radius:12px;
    box-shadow:0 18px 50px rgba(0,0,0,.55);
  }
  canvas{
    display:block;
    width:440px;
    height:440px;
    background:#0b0f14;
    border-radius:6px;
    image-rendering:pixelated;
  }
  .overlay{
    position:absolute;
    inset:10px;
    border-radius:6px;
    display:none;
    align-items:center;
    justify-content:center;
    flex-direction:column;
    gap:6px;
    background:rgba(9,12,16,.78);
    backdrop-filter:blur(2px);
    text-align:center;
  }
  .overlay.show{display:flex}
  .overlay .big{font-size:24px;letter-spacing:.15em;text-transform:uppercase}
  .overlay .small{font-size:13px;color:var(--muted)}
  .controls{display:flex;gap:10px}
  button{
    font:inherit;
    font-size:14px;
    color:var(--text);
    background:#1d242e;
    border:1px solid var(--line);
    border-radius:8px;
    padding:9px 18px;
    cursor:pointer;
    transition:background .12s ease,border-color .12s ease,transform .05s ease;
  }
  button:hover{background:#252e3a;border-color:#39414d}
  button:active{transform:translateY(1px)}
  #start{border-color:var(--accent-dim);color:#c9f5d2}
  #start:hover{background:#1c2f22}
  .hint{font-size:12px;color:#6b7683;letter-spacing:.05em}
</style>
</head>
<body>
<div class="wrap">
  <h1>Snake</h1>
  <div class="hud">
    <div>Score <span id="score">0</span></div>
    <div>Best <b id="best">0</b></div>
  </div>
  <div class="board">
    <canvas id="snake" width="440" height="440"></canvas>
    <div class="overlay" id="overlay">
      <div class="big" id="overTitle">Ready</div>
      <div class="small" id="overText">Press Start &middot; steer with arrow keys</div>
    </div>
  </div>
  <div class="controls">
    <button id="start">Start</button>
    <button id="pause">Pause</button>
    <button id="reset">Reset</button>
  </div>
  <div class="hint">&#8592; &#8593; &#8595; &#8594; to steer &middot; Space to pause</div>
</div>

<script>
(function () {
  var W = 20, H = 20;                 // grid cells
  var canvas = document.getElementById('snake');
  var ctx = canvas.getContext('2d');
  var CELL = canvas.width / W;        // 22px per cell

  var scoreEl = document.getElementById('score');
  var bestEl = document.getElementById('best');
  var overlay = document.getElementById('overlay');
  var overTitle = document.getElementById('overTitle');
  var overText = document.getElementById('overText');

  var snake, dir, pendingDir, food, alive, score, best = 0, started = false;
  var timer = null, speed = 110;

  var DIRS = {
    up:    [0, -1],
    down:  [0, 1],
    left:  [-1, 0],
    right: [1, 0]
  };

  function eq(a, b) { return a[0] === b[0] && a[1] === b[1]; }

  function occupied(x, y) {
    for (var i = 0; i < snake.length; i++) {
      if (snake[i][0] === x && snake[i][1] === y) return true;
    }
    return false;
  }

  function placeFood() {
    var free = [];
    for (var y = 0; y < H; y++) {
      for (var x = 0; x < W; x++) {
        if (!occupied(x, y)) free.push([x, y]);
      }
    }
    if (!free.length) { food = null; return; }
    food = free[Math.floor(Math.random() * free.length)].slice();
  }

  function reset() {
    var cy = Math.floor(H / 2), cx = Math.floor(W / 2);
    snake = [[cx, cy], [cx - 1, cy], [cx - 2, cy]];
    dir = 'right';
    pendingDir = null;
    alive = true;
    score = 0;
    placeFood();
    stop();
    started = false;
    showOverlay('Ready', 'Press Start \u00b7 steer with arrow keys');
    render();
  }

  function setDir(d) {
    if (!DIRS[d]) return;
    var cur = DIRS[pendingDir || dir];
    var next = DIRS[d];
    if (cur[0] + next[0] === 0 && cur[1] + next[1] === 0) return; // 180deg reversal
    pendingDir = d;
  }

  function setFood(x, y) {
    x = Math.floor(x); y = Math.floor(y);
    if (x < 0 || y < 0 || x >= W || y >= H) return;
    food = [x, y];
    render();
  }

  function die() {
    alive = false;
    stop();
    if (score > best) { best = score; bestEl.textContent = best; }
    showOverlay('Game Over', 'Score ' + score + ' \u00b7 press Reset to play again');
    render();
  }

  function tick() {
    if (!alive) return;
    if (pendingDir) { dir = pendingDir; pendingDir = null; }

    var d = DIRS[dir];
    var head = snake[0];
    var nx = head[0] + d[0];
    var ny = head[1] + d[1];

    if (nx < 0 || ny < 0 || nx >= W || ny >= H) { die(); return; }

    var eating = !!(food && food[0] === nx && food[1] === ny);

    // Body collision: the tail cell frees up this tick unless we're growing.
    var limit = eating ? snake.length : snake.length - 1;
    for (var i = 0; i < limit; i++) {
      if (snake[i][0] === nx && snake[i][1] === ny) { die(); return; }
    }

    snake.unshift([nx, ny]);
    if (eating) {
      score += 1;
      placeFood();
    } else {
      snake.pop();
    }
    render();
  }

  /* ---------- rendering ---------- */

  function roundRect(x, y, w, h, r) {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
  }

  function render() {
    ctx.fillStyle = '#0b0f14';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // subtle grid
    ctx.strokeStyle = 'rgba(255,255,255,0.035)';
    ctx.lineWidth = 1;
    for (var i = 1; i < W; i++) {
      ctx.beginPath();
      ctx.moveTo(i * CELL + 0.5, 0);
      ctx.lineTo(i * CELL + 0.5, canvas.height);
      ctx.stroke();
    }
    for (var j = 1; j < H; j++) {
      ctx.beginPath();
      ctx.moveTo(0, j * CELL + 0.5);
      ctx.lineTo(canvas.width, j * CELL + 0.5);
      ctx.stroke();
    }

    // food
    if (food) {
      var fx = food[0] * CELL, fy = food[1] * CELL;
      ctx.save();
      ctx.shadowColor = 'rgba(248,81,73,.75)';
      ctx.shadowBlur = 12;
      ctx.fillStyle = '#f85149';
      ctx.beginPath();
      ctx.arc(fx + CELL / 2, fy + CELL / 2, CELL * 0.33, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }

    // snake
    for (var k = snake.length - 1; k >= 0; k--) {
      var s = snake[k];
      var t = snake.length > 1 ? k / (snake.length - 1) : 0;
      var pad = 2;
      if (k === 0) {
        ctx.fillStyle = '#6ee787';
        ctx.shadowColor = 'rgba(63,185,80,.6)';
        ctx.shadowBlur = 10;
      } else {
        var g = Math.round(185 - 70 * t);
        var b = Math.round(80 + 20 * t);
        ctx.fillStyle = 'rgb(' + Math.round(63 - 20 * t) + ',' + g + ',' + b + ')';
        ctx.shadowBlur = 0;
      }
      roundRect(s[0] * CELL + pad, s[1] * CELL + pad, CELL - pad * 2, CELL - pad * 2, 4);
      ctx.fill();
      ctx.shadowBlur = 0;
    }

    scoreEl.textContent = score;
  }

  function showOverlay(title, text) {
    overTitle.textContent = title;
    overText.textContent = text;
    overlay.classList.add('show');
  }
  function hideOverlay() { overlay.classList.remove('show'); }

  /* ---------- loop / controls ---------- */

  function stop() {
    if (timer !== null) { clearInterval(timer); timer = null; }
  }
  function start() {
    if (!alive) return;
    if (timer !== null) return;
    started = true;
    hideOverlay();
    timer = setInterval(tick, speed);
  }
  function pause() {
    if (timer !== null) {
      stop();
      showOverlay('Paused', 'Press Start to resume');
    } else if (alive && started) {
      start();
    }
  }

  document.getElementById('start').addEventListener('click', start);
  document.getElementById('pause').addEventListener('click', pause);
  document.getElementById('reset').addEventListener('click', function () { reset(); });

  var KEYS = {
    ArrowUp: 'up', ArrowDown: 'down', ArrowLeft: 'left', ArrowRight: 'right',
    w: 'up', s: 'down', a: 'left', d: 'right'
  };
  window.addEventListener('keydown', function (e) {
    var d = KEYS[e.key];
    if (d) {
      e.preventDefault();
      setDir(d);
      if (timer === null && alive && !started) start();
      return;
    }
    if (e.key === ' ') { e.preventDefault(); pause(); }
  });

  window.game = {
    w: W,
    h: H,
    reset: reset,
    tick: tick,
    setDir: setDir,
    setFood: setFood,
    snake: function () { return snake.map(function (s) { return [s[0], s[1]]; }); },
    food: function () { return food ? [food[0], food[1]] : null; },
    alive: function () { return alive; },
    score: function () { return score; },
    start: start,
    pause: pause
  };

  reset();
})();
</script>
</body>
</html>
